"""Install baked vanilla front-face PNGs. No network or Pillow is needed.
Sources and pinned commit are documented in Images/UI/rotation_frames/SOURCE.json.
This installer never overwrites a different existing file.
"""
import base64, json, zlib
from pathlib import Path
ROOT = Path(__file__).resolve().parents[2]
PAYLOAD = ""
if __name__ == "__main__":
    for name, data in json.loads(zlib.decompress(base64.b64decode(PAYLOAD))).items():
        path = ROOT / name
        raw = base64.b64decode(data)
        if path.exists() and path.read_bytes() != raw:
            raise RuntimeError("Refusing to overwrite modified asset: " + name)
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(raw)
    print("Installed rotation frame, cross/check and 21 matching mob portraits.")
